{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances_raw = case['distances']

    # Build distance lookup
    dist_dict = {}
    for u, v, d in distances_raw:
        if u > v:
            u, v = v, u
        key = (u, v)
        if key in dist_dict:
            raise ValueError(f'Duplicate distance entry for {key}')
        dist_dict[key] = d

    edges = []
    n = len(nodes)
    for i in range(n):
        for j in range(i + 1, n):
            u = nodes[i]
            v = nodes[j]
            key = (u, v)
            if key not in dist_dict:
                raise ValueError(f'Missing distance between {u} and {v}')
            d = dist_dict[key]
            w = max(core_dist[u], core_dist[v], d)
            edges.append((w, u, v))

    # Sort deterministic: weight, then u, then v (already u<v)
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    target = n - 1

    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == target:
                break

    if len(mst_edges) != target:
        raise ValueError('Graph is disconnected, cannot form MST')

    return {'mst_edges': mst_edges, 'total_weight': total_weight}"
}
